package br.com.mecaniQA.api.Repository;
import br.com.mecaniQA.api.model.*; import br.com.mecaniQA.api.Mappers.OrdemServicoResultSetMapper; import br.com.mecaniQA.api.Enums.*; import java.sql.*; import java.util.*; import java.time.*;
public class OrdemServicoRepository extends JdbcSupport implements Repository<OrdemServico,Long>{private static final OrdemServicoRepository INSTANCE=new OrdemServicoRepository();public static OrdemServicoRepository getInstance(){return INSTANCE;}public OrdemServico cadastrar(OrdemServico x){return save(x);}public List<OrdemServico>listarTodas(){return findAll();}public OrdemServico buscarPorNumero(Long n){return findById(n).orElse(null);}public List<OrdemServico>buscarPorClienteId(Long id){return query("SELECT * FROM ordens_servico WHERE id_cliente=?",new OrdemServicoResultSetMapper()::map,id);}public List<OrdemServico>buscarPorVeiculoId(Long id){return query("SELECT * FROM ordens_servico WHERE id_veiculo=?",new OrdemServicoResultSetMapper()::map,id);}public List<OrdemServico>buscarPorStatus(StatusOrdemServico s){return query("SELECT * FROM ordens_servico WHERE status=?",new OrdemServicoResultSetMapper()::map,s.name());}public OrdemServico atualizar(Long id,OrdemServico x){x.setNumeroOS(id);return update(x);}public OrdemServico atualizarStatus(Long id,StatusOrdemServico s){OrdemServico x=buscarPorNumero(id);if(x==null)return null;x.setStatus(s);if(s==StatusOrdemServico.EXECUTADO)x.finalizar();return update(x);}public OrdemServico deletar(Long id){OrdemServico x=buscarPorNumero(id);if(x!=null)deleteById(id);return x;}public int getTotalOrdensServico(){return findAll().size();}public void limpar(){execute("DELETE FROM ordens_servico");}
 public OrdemServico save(OrdemServico x){long id=insert("INSERT INTO ordens_servico(id_cliente,id_veiculo,status,descricao_problema,observacoes,valor_total) VALUES(?,?,?,?,?,?)",x.getCliente().getIdCliente(),x.getVeiculo().getIdVeiculo(),x.getStatus().name(),x.getDescricaoProblema(),x.getObservacoes(),x.getValorTotal());x.setNumeroOS(id);return x;}public Optional<OrdemServico>findById(Long id){return query("SELECT * FROM ordens_servico WHERE numero_os=?",new OrdemServicoResultSetMapper()::map,id).stream().findFirst();}public List<OrdemServico>findAll(){return query("SELECT * FROM ordens_servico ORDER BY numero_os",new OrdemServicoResultSetMapper()::map);}public OrdemServico update(OrdemServico x){int n=execute("UPDATE ordens_servico SET id_cliente=?,id_veiculo=?,status=?,descricao_problema=?,observacoes=?,valor_total=?,data_atualizacao=CURRENT_TIMESTAMP WHERE numero_os=?",x.getCliente().getIdCliente(),x.getVeiculo().getIdVeiculo(),x.getStatus().name(),x.getDescricaoProblema(),x.getObservacoes(),x.getValorTotal(),x.getNumeroOS());return n==0?null:x;}public void deleteById(Long id){execute("DELETE FROM ordens_servico WHERE numero_os=?",id);}public boolean existsById(Long id){return !query("SELECT numero_os FROM ordens_servico WHERE numero_os=?",r->r.getLong(1),id).isEmpty();}private OrdemServico map(ResultSet r)throws SQLException{Cliente c=new Cliente();setId(c,"idCliente",r.getLong("id_cliente"));Veiculo v=new Veiculo();setId(v,"idVeiculo",r.getLong("id_veiculo"));v.setCliente(c);OrdemServico x=OrdemServico.builder().comCliente(c).comVeiculo(v).comDescricaoProblema(Optional.ofNullable(r.getString("descricao_problema")).orElse("Descrição não informada")).comStatus(StatusOrdemServico.valueOf(r.getString("status"))).comObservacoes(r.getString("observacoes")).comValorTotal(r.getDouble("valor_total")).build();setId(x,"numeroOS",r.getLong("numero_os"));x.setDataAtualizacao(time(r,"data_atualizacao"));x.setDataFinalizacao(time(r,"data_finalizacao"));return x;}}
